(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.02-t*0.25)*18 + Math.sin(x*0.016+t*0.32)*12;
  const mx = x+w1x, my = y+w1y;
  const w2x = Math.sin(mx*0.025-t*0.4)*8 + Math.cos(my*0.02+t*0.35)*6;
  const w2y = Math.cos(my*0.022+t*0.38)*8 + Math.sin(mx*0.028-t*0.3)*6;
  const sx = mx+w2x, sy = my+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.8],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1.2],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.9],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,1.1],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.7],
    [80+Math.sin(t*0.45+3)*70,120+Math.cos(t*0.65+4)*60,0.11,2.1,0.85],
    [400+Math.cos(t*0.55+2)*60,200+Math.sin(t*0.75+1)*50,0.13,1.8,1.05]
  ];
  let aS=0,iS=0,aS2=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*w;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    aS2+=Math.sin(d*f*1.3-t*sp*0.8+2.0)*w*0.5;
  }
  const act=aS/8,inh=iS/8,act2=aS2/8;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2+Math.sin(sx*0.07+sy*0.05-t*1.5)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4+Math.sin(dist*0.08+ang*2-t*2.0)*0.2+Math.sin(dist*0.03-ang*5+t*0.8)*0.15;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const reaction2=Math.tanh((act2+reaction*0.5+spiral*0.3)*1.8);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const detail=Math.sin(sx*0.3+Math.sin(sy*0.2+t)*2)*Math.sin(sy*0.3+Math.sin(sx*0.2-t)*2)*0.15;
  const blend=reaction*0.5+reaction2*0.2+cell*0.2+detail*0.1;
  const v=blend*0.5+0.5;
  const shift=Math.sin(t*0.15)*0.5+0.5;
  const pal=[
    [5,12,52],[12,45,88],[18,88,112],[30,148,138],[90,175,125],
    [175,200,85],[220,180,65],[210,130,55],[185,80,60],[150,45,72],
    [85,22,58],[35,14,48],[5,12,52]
  ];
  const pl=pal.length;
  const offset=shift*(pl-1);
  const vi=(v*(pl-1)+offset)%(pl-1);
  const i=Math.min(vi|0,pl-2),f=vi-i;
  const lum=0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge=Math.abs(reaction)>0.65?1.12:1.0;
  const vig=1.0-Math.sqrt((x-cx)**2+(y-cy)**2)/380*0.3;
  const lf=lum*edge*vig;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lf)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lf)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lf)|0
  ];
}
